SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE IF NOT EXISTS roles(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60) NOT NULL UNIQUE,descripcion VARCHAR(150),estado TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS permisos(id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(60) NOT NULL UNIQUE,nombre VARCHAR(80) NOT NULL,descripcion VARCHAR(150)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS usuarios(id BIGINT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,estado TINYINT NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS usuario_rol(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,rol_id INT NOT NULL,assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_usuario_rol(usuario_id,rol_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(rol_id) REFERENCES roles(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rol_permiso(id BIGINT AUTO_INCREMENT PRIMARY KEY,rol_id INT NOT NULL,permiso_id INT NOT NULL,UNIQUE KEY uq_rol_permiso(rol_id,permiso_id),FOREIGN KEY(rol_id) REFERENCES roles(id),FOREIGN KEY(permiso_id) REFERENCES permisos(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS empresas(id INT AUTO_INCREMENT PRIMARY KEY,ruc CHAR(11) NOT NULL UNIQUE,razon_social VARCHAR(150) NOT NULL,nombre_comercial VARCHAR(120),estado TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS departamentos(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS provincias(id INT AUTO_INCREMENT PRIMARY KEY,departamento_id INT NOT NULL,nombre VARCHAR(60) NOT NULL,UNIQUE KEY uq_provincia(departamento_id,nombre),FOREIGN KEY(departamento_id) REFERENCES departamentos(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS distritos(id INT AUTO_INCREMENT PRIMARY KEY,provincia_id INT NOT NULL,nombre VARCHAR(60) NOT NULL,UNIQUE KEY uq_distrito(provincia_id,nombre),FOREIGN KEY(provincia_id) REFERENCES provincias(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sucursales(id INT AUTO_INCREMENT PRIMARY KEY,empresa_id INT NOT NULL,codigo VARCHAR(20) NOT NULL UNIQUE,nombre VARCHAR(120) NOT NULL,direccion VARCHAR(180),distrito_id INT NULL,estado TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(empresa_id) REFERENCES empresas(id),FOREIGN KEY(distrito_id) REFERENCES distritos(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS almacenes(id INT AUTO_INCREMENT PRIMARY KEY,sucursal_id INT NOT NULL,codigo VARCHAR(20) NOT NULL UNIQUE,nombre VARCHAR(120) NOT NULL,tipo VARCHAR(40),estado TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(sucursal_id) REFERENCES sucursales(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS clientes(id BIGINT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(20),tipo_doc CHAR(2),nro_doc VARCHAR(15) NOT NULL UNIQUE,razon_social VARCHAR(150) NOT NULL,departamento_id INT NULL,provincia_id INT NULL,distrito_id INT NULL,FOREIGN KEY(departamento_id) REFERENCES departamentos(id),FOREIGN KEY(provincia_id) REFERENCES provincias(id),FOREIGN KEY(distrito_id) REFERENCES distritos(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vendedores(id BIGINT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(20) NOT NULL UNIQUE,nombres VARCHAR(120) NOT NULL,apellidos VARCHAR(120),email VARCHAR(120),estado TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categorias_producto(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60) NOT NULL,descripcion VARCHAR(120)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS marcas(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(60) NOT NULL,fabricante VARCHAR(80)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS unidades_medida(id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(10) NOT NULL UNIQUE,nombre VARCHAR(40) NOT NULL,abreviatura VARCHAR(10),factor_base DECIMAL(12,4) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS productos(id BIGINT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(150) NOT NULL,categoria_id INT NULL,marca_id INT NULL,unidad_base_id INT NULL,estado TINYINT NOT NULL DEFAULT 1,FOREIGN KEY(categoria_id) REFERENCES categorias_producto(id),FOREIGN KEY(marca_id) REFERENCES marcas(id),FOREIGN KEY(unidad_base_id) REFERENCES unidades_medida(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tipos_documento(id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(4) NOT NULL UNIQUE,nombre VARCHAR(60) NOT NULL,sunat_code VARCHAR(4)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS partners(id INT AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(20) NOT NULL UNIQUE,nombre VARCHAR(80) NOT NULL,tipo VARCHAR(30)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS documentos_cabecera(id BIGINT AUTO_INCREMENT PRIMARY KEY,tipo_documento_id INT NOT NULL,numero VARCHAR(25) NOT NULL,fecha DATE NOT NULL,cliente_id BIGINT NOT NULL,vendedor_id BIGINT NOT NULL,sucursal_id INT NOT NULL,estado_registro VARCHAR(20) NOT NULL DEFAULT 'BORRADOR',created_by BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at DATETIME NULL,UNIQUE KEY uq_doc(tipo_documento_id,numero),FOREIGN KEY(tipo_documento_id) REFERENCES tipos_documento(id),FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(vendedor_id) REFERENCES vendedores(id),FOREIGN KEY(sucursal_id) REFERENCES sucursales(id),FOREIGN KEY(created_by) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS documentos_detalle(id BIGINT AUTO_INCREMENT PRIMARY KEY,documento_id BIGINT NOT NULL,producto_id BIGINT NOT NULL,unidad_id INT NOT NULL,cantidad DECIMAL(14,3) NOT NULL,valor_unitario DECIMAL(14,2) NOT NULL DEFAULT 0,FOREIGN KEY(documento_id) REFERENCES documentos_cabecera(id) ON DELETE CASCADE,FOREIGN KEY(producto_id) REFERENCES productos(id),FOREIGN KEY(unidad_id) REFERENCES unidades_medida(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS guias_cabecera(id BIGINT AUTO_INCREMENT PRIMARY KEY,numero VARCHAR(25) NOT NULL UNIQUE,fecha DATE NOT NULL,cliente_id BIGINT NOT NULL,vendedor_id BIGINT NOT NULL,sucursal_id INT NOT NULL,departamento_id INT NULL,provincia_id INT NULL,distrito_id INT NULL,estado_registro VARCHAR(20) NOT NULL DEFAULT 'BORRADOR',created_by BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at DATETIME NULL,FOREIGN KEY(cliente_id) REFERENCES clientes(id),FOREIGN KEY(vendedor_id) REFERENCES vendedores(id),FOREIGN KEY(sucursal_id) REFERENCES sucursales(id),FOREIGN KEY(departamento_id) REFERENCES departamentos(id),FOREIGN KEY(provincia_id) REFERENCES provincias(id),FOREIGN KEY(distrito_id) REFERENCES distritos(id),FOREIGN KEY(created_by) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS guias_detalle(id BIGINT AUTO_INCREMENT PRIMARY KEY,guia_id BIGINT NOT NULL,producto_id BIGINT NOT NULL,unidad_id INT NOT NULL,cantidad DECIMAL(14,3) NOT NULL,FOREIGN KEY(guia_id) REFERENCES guias_cabecera(id) ON DELETE CASCADE,FOREIGN KEY(producto_id) REFERENCES productos(id),FOREIGN KEY(unidad_id) REFERENCES unidades_medida(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_cabecera(id BIGINT AUTO_INCREMENT PRIMARY KEY,fecha_stock DATE NOT NULL,almacen_id INT NOT NULL,estado_registro VARCHAR(20) NOT NULL DEFAULT 'BORRADOR',created_by BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,published_at DATETIME NULL,FOREIGN KEY(almacen_id) REFERENCES almacenes(id),FOREIGN KEY(created_by) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS lotes(id BIGINT AUTO_INCREMENT PRIMARY KEY,producto_id BIGINT NOT NULL,codigo_lote VARCHAR(40) NOT NULL,fecha_vencimiento DATE NULL,estado TINYINT NOT NULL DEFAULT 1,UNIQUE KEY uq_lote(producto_id,codigo_lote),FOREIGN KEY(producto_id) REFERENCES productos(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS stock_detalle(id BIGINT AUTO_INCREMENT PRIMARY KEY,stock_id BIGINT NOT NULL,lote_id BIGINT NULL,producto_id BIGINT NOT NULL,unidad_id INT NOT NULL,cantidad DECIMAL(14,3) NOT NULL,FOREIGN KEY(stock_id) REFERENCES stock_cabecera(id) ON DELETE CASCADE,FOREIGN KEY(lote_id) REFERENCES lotes(id),FOREIGN KEY(producto_id) REFERENCES productos(id),FOREIGN KEY(unidad_id) REFERENCES unidades_medida(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homologacion_productos_bayer(id BIGINT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,producto_id BIGINT NOT NULL,material_id VARCHAR(40) NOT NULL,material_name VARCHAR(150),unidad_bayer_id INT NULL,UNIQUE KEY uq_hpb(partner_id,producto_id),FOREIGN KEY(partner_id) REFERENCES partners(id),FOREIGN KEY(producto_id) REFERENCES productos(id),FOREIGN KEY(unidad_bayer_id) REFERENCES unidades_medida(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homologacion_clientes(id BIGINT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,cliente_id BIGINT NOT NULL,customer_id VARCHAR(40),customer_name VARCHAR(150),UNIQUE KEY uq_hc(partner_id,cliente_id),FOREIGN KEY(partner_id) REFERENCES partners(id),FOREIGN KEY(cliente_id) REFERENCES clientes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homologacion_unidades(id BIGINT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,unidad_id INT NOT NULL,external_unit_code VARCHAR(20),external_unit_name VARCHAR(60),UNIQUE KEY uq_hu(partner_id,unidad_id),FOREIGN KEY(partner_id) REFERENCES partners(id),FOREIGN KEY(unidad_id) REFERENCES unidades_medida(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homologacion_sucursales(id BIGINT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,sucursal_id INT NOT NULL,branch_id VARCHAR(20),branch_name VARCHAR(120),UNIQUE KEY uq_hs(partner_id,sucursal_id),FOREIGN KEY(partner_id) REFERENCES partners(id),FOREIGN KEY(sucursal_id) REFERENCES sucursales(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homologacion_almacenes(id BIGINT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,almacen_id INT NOT NULL,warehouse_id VARCHAR(20),warehouse_name VARCHAR(120),UNIQUE KEY uq_ha(partner_id,almacen_id),FOREIGN KEY(partner_id) REFERENCES partners(id),FOREIGN KEY(almacen_id) REFERENCES almacenes(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS homologacion_vendedores(id BIGINT AUTO_INCREMENT PRIMARY KEY,partner_id INT NOT NULL,vendedor_id BIGINT NOT NULL,sales_id VARCHAR(20),sales_name VARCHAR(120),UNIQUE KEY uq_hv(partner_id,vendedor_id),FOREIGN KEY(partner_id) REFERENCES partners(id),FOREIGN KEY(vendedor_id) REFERENCES vendedores(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS validaciones(id BIGINT AUTO_INCREMENT PRIMARY KEY,modulo VARCHAR(30) NOT NULL,registro_id BIGINT NOT NULL,usuario_id BIGINT NOT NULL,resultado VARCHAR(20) NOT NULL,observacion TEXT,validated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS publicaciones(id BIGINT AUTO_INCREMENT PRIMARY KEY,modulo VARCHAR(30) NOT NULL,fecha_publicacion DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,usuario_id BIGINT NOT NULL,estado VARCHAR(20) NOT NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS detalle_publicacion(id BIGINT AUTO_INCREMENT PRIMARY KEY,publicacion_id BIGINT NOT NULL,registro_id BIGINT NOT NULL,dataset VARCHAR(30) NOT NULL,FOREIGN KEY(publicacion_id) REFERENCES publicaciones(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS exportaciones(id BIGINT AUTO_INCREMENT PRIMARY KEY,tipo_dataset VARCHAR(30) NOT NULL,formato VARCHAR(10) NOT NULL,filtro_json JSON NULL,usuario_id BIGINT NOT NULL,generated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS auditoria_acciones(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NOT NULL,modulo VARCHAR(30) NOT NULL,accion VARCHAR(30) NOT NULL,entidad_id BIGINT NULL,fecha_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS bitacora_acceso(id BIGINT AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT NULL,ip VARCHAR(45),user_agent VARCHAR(255),accion VARCHAR(30),fecha_hora DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
SET FOREIGN_KEY_CHECKS=1;
